                Blocks(Paragraph(Text("The real matrix acts on complex states so nonreal poles are included."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("complex-matrix-mul"),
                DeclarationHandle.Create("D5/S3/Observer/Hankel/DiscreteSteinCompressionStability.complexMatrix_mul"), H("Complexified products"),
                StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Complexification preserves the actual matrix products used in iterated readouts."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("complex-energy"),
                DeclarationHandle.Create("D5/S3/Observer/Hankel/DiscreteSteinCompressionStability.complexEnergy"), H("Complex state energy"),
                StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Positive diagonal weights measure the sum of squared complex moduli."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("energy-nonnegative"),
