                StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every nonzero complex eigenvector carries strictly positive energy."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("energy-scaling"),
